import sys

def max_profit_brute(k, prices):
    n = len(prices)
    if n <= 1 or k == 0:
        return 0
    dp = [[[0, 0] for _ in range(k + 1)] for _ in range(n)]
    for j in range(1, k + 1):
        dp[0][j][1] = -prices[0]
    for i in range(1, n):
        for j in range(1, k + 1):
            dp[i][j][0] = max(dp[i - 1][j][0], dp[i - 1][j][1] + prices[i])
            dp[i][j][1] = max(dp[i - 1][j][1], dp[i - 1][j - 1][0] - prices[i])
    return max(dp[n - 1][j][0] for j in range(k + 1))

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    k = int(data[0]); n = int(data[1])
    prices = list(map(int, data[2:2 + n]))
    print(max_profit_brute(k, prices))

import sys

def max_profit_opt(k, prices):
    n = len(prices)
    if n <= 1 or k == 0:
        return 0
    if k >= n // 2:
        return sum(max(0, prices[i + 1] - prices[i]) for i in range(n - 1))
    dp = [[0] * n for _ in range(k + 1)]
    for i in range(1, k + 1):
        max_diff = -prices[0]
        for j in range(1, n):
            dp[i][j] = max(dp[i][j - 1], prices[j] + max_diff)
            max_diff = max(max_diff, dp[i - 1][j] - prices[j])
    return dp[k][n - 1]

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    k = int(data[0]); n = int(data[1])
    prices = list(map(int, data[2:2 + n]))
    print(max_profit_opt(k, prices))

import sys

def max_profit_best(k, prices):
    n = len(prices)
    if n <= 1 or k == 0:
        return 0
    if k >= n // 2:
        return sum(max(0, prices[i + 1] - prices[i]) for i in range(n - 1))
    buy = [float('-inf')] * (k + 1)
    sell = [0] * (k + 1)
    for price in prices:
        for j in range(1, k + 1):
            buy[j] = max(buy[j], sell[j - 1] - price)
            sell[j] = max(sell[j], buy[j] + price)
    return sell[k]

if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    k = int(data[0]); n = int(data[1])
    prices = list(map(int, data[2:2 + n]))
    print(max_profit_best(k, prices))
